grammar.example:
const user = { name: 'Kim' };
user.name = 'Lee'; // 내부 프로퍼티 변경 가능
console.log(user.name);

const options = { host: 'localhost', port: 8080 };
const config = { ...options, secure: true };
console.log(config.port);

class Animal {
    constructor(name) {
        this.name = name;
    }
    speak() {
        return `${this.name} makes a noise.`;
    }
}
const dog = new Animal('Maltese');
console.log(dog.speak());

const settings = { volume: 0 };
const vol = settings.volume ?? 50; // 0이 유지됨 (||와 달리 0을 falsy로 보지 않음)
console.log(vol);

